set -euo pipefail

# Question 4: Unhealthy worker
case "${Q4_FAULT}" in
  kubelet-stopped) ;;
  containerd-stopped) ;;
  kubelet-binary-path) ;;
  cordoned)
    kubectl uncordon "${Q4_NODE}"
    ;;
  stray-taint)
    kubectl taint node "${Q4_NODE}" maintenance-
    ;;
esac

case "${Q4_FAULT}" in
  kubelet-stopped)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q4_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" == True ]] && break
      sleep 2
    done
    ;;
  containerd-stopped)
